solution.solution.py:
def to_binary(n):
    if n == 0:
        return "0"
    bits = ""
    while n > 0:
        bits = str(n % 2) + bits
        n //= 2
    return bits

def from_binary(text):
    value = 0
    for ch in text:
        value = value * 2 + (1 if ch == "1" else 0)
    return value

unitTests:
@test("to binary")
def _():
    check_eq(to_binary(0), "0")
    check_eq(to_binary(1), "1")
    check_eq(to_binary(2), "10")
    check_eq(to_binary(13), "1101")
    check_eq(to_binary(77), "1001101")
    check_eq(to_binary(255), "11111111")
    check_eq(to_binary(1024), "10000000000")

@test("from binary")
def _():
    check_eq(from_binary("0"), 0)
    check_eq(from_binary("1101"), 13)
    check_eq(from_binary("01001101"), 77)
    check_eq(from_binary("11111111"), 255)

@test("there and back")
def _():
    for n in [0, 5, 100, 4096, 123456789]:
        check_eq(from_binary(to_binary(n)), n)

